<title>Mendel’s Pea Parlour</title>
<style>
:root{--ink:#173c2e;--paper:#f5efd9;--rust:#ab512d;--plum:#80468b;--line:#b4b69b}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Palatino Linotype",Palatino,"Book Antiqua",serif;font-size:18px;line-height:1.5;background-image:radial-gradient(#667a4920 .7px,transparent .7px);background-size:5px 5px}
main{max-width:1160px;margin:auto;padding:25px 28px 60px}a{color:inherit;text-underline-offset:4px}nav{display:flex;justify-content:space-between;border-bottom:1px solid var(--ink);padding-bottom:14px;font:12px "Courier New",monospace;letter-spacing:1px}
header{display:grid;grid-template-columns:1.3fr 1fr;gap:30px;align-items:end;padding:35px 0 27px}.eyebrow,.label{font:12px "Courier New",monospace;text-transform:uppercase;letter-spacing:2px}.eyebrow{color:var(--rust)}h1{font-size:clamp(45px,7vw,82px);line-height:.96;font-weight:normal;letter-spacing:-3px;margin:12px 0}h1 em{color:var(--rust)}header p{max-width:390px;margin:0 0 6px;font-size:19px}
.lab{display:grid;grid-template-columns:350px 1fr;border:1px solid var(--ink);box-shadow:7px 7px 0 #173c2e12;background:#fcf8e9}.bench{padding:24px;border-right:1px solid var(--ink)}h2{font-size:28px;line-height:1.1;font-weight:normal;margin:10px 0 16px}p{margin:10px 0 17px}.small{font-size:15px;color:#455b46}.rounds{display:flex;gap:6px;margin:14px 0}button,select,input{font:inherit}button{cursor:pointer;border:1px solid var(--ink);background:transparent;color:var(--ink);padding:11px 14px;border-radius:2px;min-height:44px}button:hover{background:#dde3c8}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid var(--rust);outline-offset:3px}.rounds button{flex:1;font:13px "Courier New",monospace;padding:8px 5px}.rounds button[aria-pressed=true]{background:var(--ink);color:var(--paper)}
.parents{display:grid;grid-template-columns:1fr 1fr;gap:14px}.parents label{display:block;font:12px "Courier New",monospace;margin-bottom:7px}select{width:100%;background:#f5efd9;border:1px solid var(--line);padding:9px;color:var(--ink)}.parent-note{font-size:14px;min-height:44px;margin:5px 0 16px}.prediction{border-top:1px dashed var(--line);padding-top:15px}.prediction label{display:block}input[type=range]{width:100%;accent-color:var(--plum);margin:18px 0}.guess{font-size:38px;line-height:1.2;display:block;color:var(--plum)}.primary{background:var(--ink);color:var(--paper);width:100%}.primary:hover{background:#2c5540}.stamp{margin-top:16px;min-height:74px;font-size:16px}
.garden-panel{min-width:0;display:flex;flex-direction:column}.garden{position:relative;min-height:350px;background:#d2d6b0;overflow:hidden;border-bottom:1px solid var(--ink)}.garden-art{position:absolute;width:100%;height:100%;object-fit:cover;object-position:center;opacity:.92}.garden-tag{position:absolute;top:18px;left:18px;background:#fbf6e6ed;padding:6px 12px;border:1px solid #173c2e80;font:12px "Courier New",monospace;z-index:1}
.specimens{position:absolute;bottom:24px;left:15%;right:15%;display:grid;grid-template-columns:repeat(8,1fr);gap:5px;background:#edf0dacf;border:1px solid #173c2e55;padding:10px;border-radius:3px;min-height:112px;align-items:center}.plant{position:relative;border:0;padding:0;min-height:40px;background:none;line-height:0}.plant:hover{background:#f5efd9}.plant svg{width:100%;max-height:44px;filter:drop-shadow(0 2px 1px #173c2e44)}.plant.new{animation:sprout .55s backwards}.empty{grid-column:1/-1;text-align:center;font-style:italic;line-height:1.4;font-size:17px}.results{padding:20px 24px}.results-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.results h2{margin:0}.size{font:13px "Courier New",monospace}.size select{width:auto;padding:7px}
.meter{height:18px;border:1px solid var(--ink);background:#fff9eb;margin-top:18px;overflow:hidden}.meter span{display:block;height:100%;background:var(--plum);width:0;transition:width .4s}.meter-label{font:13px "Courier New",monospace;margin:7px 0 12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{font-size:15px}.grid-section{padding:20px 24px;border-top:1px solid var(--line);display:grid;grid-template-columns:150px 1fr;gap:20px}.punnett{width:150px;border-collapse:collapse;font:17px "Courier New",monospace;text-align:center}.punnett th{font-weight:normal;color:#516149;padding:6px}.punnett td{border:1px solid var(--line);padding:9px;background:#ece5ce}.punnett .purple{color:var(--plum);background:#eee1ee}.punnett .white{background:#fff9eb}.explanation{font-size:16px;margin:0}.summary{border:1px solid var(--line);padding:15px 18px;margin:22px 0;background:#ece8d3}.summary strong{font-weight:normal;font-size:22px}.notes{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:28px;border-top:1px solid var(--ink);padding-top:20px}.notes h3{font-weight:normal;font-size:24px;margin:0 0 8px}.notes p{font-size:16px}footer{margin-top:25px;font-size:14px}dialog{max-width:350px;border:1px solid var(--ink);background:var(--paper);color:var(--ink);padding:25px}dialog::backdrop{background:#173c2e99}
@keyframes sprout{from{transform:translateY(12px) scale(.6);opacity:0}to{transform:none;opacity:1}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
@media(max-width:760px){main{padding:18px 16px 40px}header{grid-template-columns:1fr;gap:14px;padding:28px 0}header p{max-width:none}.lab{grid-template-columns:1fr}.bench{border-right:0;border-bottom:1px solid var(--ink);padding:20px}.garden{min-height:300px}.specimens{left:10%;right:10%}.notes{grid-template-columns:1fr;gap:8px}.results-head{flex-wrap:wrap}.grid-section{grid-template-columns:125px 1fr;gap:14px;padding:18px}.punnett{width:125px}.results{padding:20px}nav{font-size:11px}h1{letter-spacing:-2px}.stamp{min-height:0}}
</style>
