<body>
<main>
<nav><a href="index.php">← Chloe Reads Jon</a><span>BOTANICAL EXPERIMENT No. 01</span></nav>
<header><div><div class="eyebrow">A small garden. An enormous discovery.</div><h1>Mendel’s<br><em>Pea Parlour.</em></h1></div><p>Two purple flowers can have a white-flowered child. Strange? Yes. Magic? No. Put on your gardening gloves and find the rule.</p></header>
<section class="lab" aria-label="Pea crossing experiment">
<div class="bench">
<div class="label" id="round-label">Experiment 1 of 3</div>
<div class="rounds" aria-label="Choose experiment"><button data-round="0" aria-pressed="true">01 / FIRST</button><button data-round="1" aria-pressed="false">02 / HIDDEN</button><button data-round="2" aria-pressed="false">03 / TEST</button></div>
<h2 id="mission">Purple meets white.</h2><p class="small" id="mission-text">Cross a pure purple plant with a white one. Will the colours mix?</p>
<div class="parents"><div><label for="parent-a">PARENT A</label><select id="parent-a"><option>PP</option><option>Pp</option><option>pp</option></select></div><div><label for="parent-b">PARENT B</label><select id="parent-b"><option>PP</option><option>Pp</option><option selected>pp</option></select></div></div>
<p class="parent-note" id="parent-note"></p>
<div class="prediction"><label for="prediction">Your prediction: how many purple flowers?</label><output class="guess" id="guess" for="prediction">50%</output><input id="prediction" type="range" min="0" max="100" step="25" value="50"><button class="primary" id="grow">Plant &amp; discover →</button></div>
<div class="stamp" id="verdict" aria-live="polite">No timer. No points. Just a wonderfully nosy gardener.</div>
</div>
<div class="garden-panel">
<div class="garden"><img class="garden-art" src="data:image/webp;base64," alt="An original botanical illustration of purple and white pea flowers surrounding a monastery garden"><div class="garden-tag" id="garden-tag">THE EXPERIMENTAL PLOT / READY</div><div class="specimens" id="specimens"><div class="empty">Your seedlings will bloom here.</div></div></div>
<div class="results">
<div class="results-head"><h2>The harvest ledger</h2><label class="size" for="batch">Batch <select id="batch"><option value="16">16 plants</option><option value="64">64 plants</option><option value="256">256 plants</option></select></label></div>
<div class="meter" aria-hidden="true"><span id="observed-meter"></span></div><div class="meter-label" id="ledger" aria-live="polite">Purple: — / White: —</div>
<div class="actions"><button id="again" disabled>Grow another batch</button><button id="next" disabled>Next experiment →</button><button id="reset">Clear plot</button></div>
<p class="small" id="sampling">A probability is a long-run pattern, not a promise about a handful of plants.</p>
</div>
<div class="grid-section"><table class="punnett" aria-label="Possible offspring, each cell equally likely"><caption class="label">The four possibilities</caption><tbody id="punnett"></tbody></table><p class="explanation" id="explanation">Each parent passes along one of its two letter-copies, chosen at random. Predict first; then open the seed envelopes.</p></div>
</div>
</section>
<div class="summary" id="specimen-summary" aria-live="polite"><strong>A field note:</strong> P and p are versions of the same gene. Every plant here gets one from each parent.</div>
<section class="notes"><div><h3>A monk with a notebook</h3><p>Gregor Mendel was an Augustinian friar who studied pea inheritance in the 1850s and 1860s. Counting thousands of plants helped him uncover patterns that made him a founder of genetics.</p></div><div><h3>The parlour’s simple rule</h3><p>In this one-trait model, <strong>PP</strong> and <strong>Pp</strong> have purple flowers. Only <strong>pp</strong> has white flowers. “Dominant” means visible with one copy, not better, stronger, or more common. Real inheritance can be more complicated.</p></div></section>
<footer>Inspired by Jon’s <a href="?source=1">Catholic thinkers in science</a>. Original botanical artwork made for this garden. All experiments run in your browser.</footer>
</main>
<dialog id="plant-dialog"><h2 id="plant-title"></h2><p id="plant-detail"></p><button id="close-dialog">Back to the garden</button></dialog>
<script>
'use strict';
const $=id=>document.getElementById(id);
const rounds=[
{a:'PP',b:'pp',title:'Purple meets white.',text:'Cross a pure purple plant with a white one. Will the colours mix?',note:'Every child is Pp and purple. The white-flower version has not vanished: it is hidden beside P.'},
{a:'Pp',b:'Pp',title:'The hidden colour returns.',text:'Two purple plants, each carrying p. Could their children have white flowers?',note:'One of four equally likely combinations is pp. White flowers return without any paint mixing.'},
{a:'Pp',b:'pp',title:'The revealing cross.',text:'Pair a purple carrier with a white plant. Predict how often the hidden letter will show itself.',note:'Half the combinations are Pp and half are pp. A cross with pp can reveal a hidden recessive copy.'}
];
let round=0,revealed=false,total=0,purple=0,white=0,latest=[],completed=new Set();
function combinations(a=$('parent-a').value,b=$('parent-b').value){return [a[0]+b[0],a[0]+b[1],a[1]+b[0],a[1]+b[1]].map(s=>s.includes('P')&&s.includes('p')?'Pp':s)}
function expected(){return combinations().filter(s=>s!=='pp').length*25}
function coin(){return crypto.getRandomValues(new Uint8Array(1))[0]&1}
function clear(){revealed=false;total=purple=white=0;latest=[];$('specimens').innerHTML='<div class="empty">Your seedlings will bloom here.</div>';$('garden-tag').textContent='THE EXPERIMENTAL PLOT / READY';$('observed-meter').style.width='0%';$('ledger').textContent='Purple: — / White: —';$('sampling').textContent='A probability is a long-run pattern, not a promise about a handful of plants.';$('verdict').textContent='No timer. No points. Just a wonderfully nosy gardener.';$('again').disabled=true;$('next').disabled=true;$('grow').textContent='Plant & discover →';$('specimen-summary').textContent='A field note: P and p are versions of the same gene. Every plant here gets one from each parent.';drawGrid();updateParents()}
function updateParents(){const name=g=>g==='PP'?'pure purple':g==='Pp'?'purple, carrying p':'white';$('parent-note').textContent='A: '+name($('parent-a').value)+' · B: '+name($('parent-b').value)}
function setRound(i){round=i;const r=rounds[i];$('parent-a').value=r.a;$('parent-b').value=r.b;$('mission').textContent=r.title;$('mission-text').textContent=r.text;$('round-label').textContent='Experiment '+(i+1)+' of 3';document.querySelectorAll('[data-round]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.round)===i)));clear()}
function drawGrid(){const a=$('parent-a').value,b=$('parent-b').value,c=combinations();$('punnett').innerHTML='<tr><th scope="col">A↓ B→</th><th scope="col">'+b[0]+'</th><th scope="col">'+b[1]+'</th></tr>'+[0,1].map(i=>'<tr><th scope="row">'+a[i]+'</th>'+[0,1].map(j=>'<td class="'+(revealed?(c[i*2+j]==='pp'?'white':'purple'):'')+'">'+(revealed?c[i*2+j]:'?')+'</td>').join('')+'</tr>').join('');$('explanation').textContent=revealed?'Expected: '+expected()+'% purple, '+(100-expected())+'% white. Each cell is a 1-in-4 possibility. The letters do not blend; they travel in pairs.':'Each parent passes along one of its two letter-copies, chosen at random. Predict first; then open the seed envelopes.'}
function flower(g,i){const color=g==='pp'?'#fffbea':'#9a5ca4';return '<button class="plant new" style="animation-delay:'+i*8+'ms" data-plant="'+i+'" aria-label="Inspect '+(g==='pp'?'white':'purple')+' flower '+(i+1)+'"><svg viewBox="0 0 36 50" aria-hidden="true"><path d="M18 48V18M18 38Q1 26 6 40Q11 46 18 42M18 30Q32 19 31 32Q26 39 18 35" stroke="#285e39" stroke-width="2" fill="#68904c"/><path d="M18 25Q-1 14 8 8Q14 3 18 14Q23 1 29 9Q38 17 18 25Z" fill="'+color+'" stroke="#694d6c" stroke-width="1"/><path d="M18 24Q7 16 13 13Q18 10 23 14Q29 18 18 24" fill="'+color+'" stroke="#694d6c"/><circle cx="18" cy="21" r="2" fill="#d9ae48"/></svg></button>'}
function harvest(){const a=$('parent-a').value,b=$('parent-b').value,n=Number($('batch').value),prediction=Number($('prediction').value),exp=expected();latest=[];for(let i=0;i<n;i++){let g=a[coin()]+b[coin()];if(g.includes('P')&&g.includes('p'))g='Pp';latest.push(g);if(g==='pp')white++;else purple++}total+=n;revealed=true;$('specimens').innerHTML=latest.slice(0,32).map(flower).join('');$('garden-tag').textContent=n>32?'LATEST BATCH / FIRST 32 OF '+n+' SHOWN':'LATEST BATCH / '+n+' PLANTS';$('observed-meter').style.width=(purple/total*100)+'%';$('ledger').textContent=purple+' purple · '+white+' white / '+total+' plants ('+(purple/total*100).toFixed(1)+'% purple)';const custom=a!==rounds[round].a||b!==rounds[round].b;$('verdict').textContent=(prediction===exp?'Right on the theoretical ratio! ':'You predicted '+prediction+'%; the theoretical ratio is '+exp+'%. ')+(custom?'Your custom cross is ready to explore.':rounds[round].note);if(!custom)completed.add(round);$('again').disabled=false;$('next').disabled=false;$('next').textContent=round===2?'Return to experiment 1':'Next experiment →';$('grow').textContent='Grow another batch →';$('sampling').textContent='Expected '+exp+'% purple; observed '+(purple/total*100).toFixed(1)+'%. '+(total>=256?'Bigger samples usually settle closer to the ratio, but not perfectly.':'Try more batches. Small gardens can give surprisingly lopsided results.');$('specimen-summary').textContent=completed.size===3?'All three experiments explored. You have recovered Mendel’s surprise: a hidden trait can reappear. Change either parent to invent your own cross.':'Tap a flower to open its seed envelope. The ledger counts every plant, including those not pictured.';drawGrid()}
$('prediction').addEventListener('input',()=>{$('guess').textContent=$('prediction').value+'%'});
$('parent-a').addEventListener('change',clear);$('parent-b').addEventListener('change',clear);
$('grow').addEventListener('click',harvest);$('again').addEventListener('click',harvest);$('next').addEventListener('click',()=>setRound((round+1)%3));$('reset').addEventListener('click',clear);
document.querySelectorAll('[data-round]').forEach(b=>b.addEventListener('click',()=>setRound(Number(b.dataset.round))));
$('specimens').addEventListener('click',e=>{const b=e.target.closest('[data-plant]');if(!b)return;const g=latest[Number(b.dataset.plant)];$('plant-title').textContent=g+' · '+(g==='pp'?'White flower':'Purple flower');$('plant-detail').textContent=g==='pp'?'Two p copies. No P copy is present, so the white-flower trait is visible.':g==='Pp'?'One P and one p. The flower is purple, but it can pass p to a child.':'Two P copies. This plant can only pass P to a child.';$('plant-dialog').showModal()});
$('close-dialog').addEventListener('click',()=>$('plant-dialog').close());
setRound(0);
</script>
</body></html>
